                self._integer = value
            elif isinstance(value, list):
                self._list = value

    def isInteger(self):
        return self._integer is not None

    def add(self, elem):
        self._list.append(elem)

    def setInteger(self, value):
        self._integer = value

    def getInteger(self):
        return self._integer

    def getList(self):
        return self._list

